# Generated by jetraw-cli's promote workflow from packaging/homebrew/jetraw-cli.rb;
# edits made here are overwritten by the next release.
class JetrawCli < Formula
  desc "Move imaging data between your machines and your cloud storage with Jetraw"
  homepage "https://platform.jetraw.com"
  url "https://github.com/Jetraw/homebrew-tap/releases/download/jetraw-cli-v0.3.4/jr-0.3.4-darwin-arm64.tar.gz"
  sha256 "01ba2a4c28589581abb36e8577b0c11bd0ea293bcc58e62315aca77ee43a0de2"

  depends_on arch: :arm64
  depends_on :macos

  conflicts_with "jr", because: "both install a `jr` binary"

  def install
    bin.install "jr"
    # Runs `jr completion bash|zsh|fish` and puts each script where its shell looks.
    generate_completions_from_executable(bin/"jr", "completion")
  end

  def caveats
    <<~EOS
      Shell completion for jr is installed for zsh, bash and fish. If Tab does not
      complete jr in zsh, add this line to ~/.zshrc and open a new terminal:
        autoload -Uz compinit && compinit
      For bash and fish, see https://docs.brew.sh/Shell-Completion
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/jr version")
    assert_path_exists bash_completion/"jr"
    assert_path_exists zsh_completion/"_jr"
    assert_path_exists fish_completion/"jr.fish"
  end
end
